# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: "/assign": a new variable written by the AI, with no UI code. The AI turns
#          "/assign [name =] <what it should hold>" into Python that ends by assigning one name
#          (propose); the user reviews and runs it (run), and the value is bound only when it is
#          structured: a basic value (str, int, float, bool, date, datetime, time, timedelta), a
#          list of those, a pydantic model of those, or a polars DataFrame. Never a dict.
#          The AI writes code rather than the value, so what was computed is exact and how it
#          was made stays visible; something it only knows is written as a literal.
#          It reads the chat so far, the session's variables (and "@" mentions) and the SmashDb
#          tables, and has no tools.
# Usage: await propose(session, token, text) -> Proposal; run(session, code) -> Ran, called by
#        State.assign_ask / assign_run. Each proposal is one "agent" debug-log record.
# Spec:  spec/experimental/reflex-kernel/variables.md ("/assign")
# ---------------------------------------------------------------------------
from __future__ import annotations

import ast
import datetime as dt
import re
import traceback
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Any, Literal

import polars as pl
from pydantic import BaseModel, Field
from pydantic_ai import Agent, ModelRetry, RunContext, capture_run_messages

from ds.util.const import DEFAULT_AI_MODEL
from ds.util.logging import log_call
from ds.util.text import clean_f_str

from . import mentions
from .inline_edit import context as python_context
from .session import log_usage, trace_parts

if TYPE_CHECKING:
    from .session import Session

# times a proposal that fails its check (not Python, assigns nothing) is sent back to the model
MAX_FIXES = 2
SOURCE = "/assign"
# "name = what it should hold" (not "==", a comparison in the text)
_NAMED = re.compile(r"\s*([A-Za-z_]\w*)\s*=(?!=)\s*(.+)", re.DOTALL)
BASIC = (str, int, float, bool, dt.date, dt.datetime, dt.time, dt.timedelta)
ALLOWED = "a str, int, float, bool, date, datetime, time or timedelta, a list of those, a pydantic model, or a polars DataFrame"
# How the AI names a variable it picks the name for, by the value's type (the user's own name is
# kept as given). One line each; the end of the instructions.
NAMING = "\n".join(
    [
        "- a DataFrame ends in _df: top_players_df",
        "- a date ends in _date: release_date; a datetime ends in _at: started_at; a time ends in _time",
        "- a timedelta ends in _duration: set_duration",
        "- a bool starts with is_, has_ or can_: is_offline",
        "- a list is a plural noun: player_tags, win_rates",
        "- a count is n_ and a plural: n_sets; another number names its unit or kind: win_rate, damage_pct",
        "- a str is a singular noun: best_char, player_tag",
        "- a record (pydantic model) is a singular noun, its class the same in PascalCase: player_summary,"
        " PlayerSummary",
    ]
)
COMPUTED, KNOWLEDGE = "computed", "knowledge"
BASIS_TEXT = {COMPUTED: "computed from your data", KNOWLEDGE: "from the AI's knowledge or the chat: not checked"}


class Assign(BaseModel):
    name: str = Field(description="The variable's name: short snake_case, a Python identifier.")
    code: str = Field(description="Python that ends by assigning that name. No Markdown fences, no explanation.")
    basis: Literal["computed", "knowledge"] = Field(
        description="computed: the value is worked out from the session's data. knowledge: you wrote it out yourself."
    )


_INSTRUCTIONS = clean_f_str(f"""
    You create one new variable in the Python session of a Super Smash Bros. Ultimate data app. The user
    says what it should hold; you answer with its name and the Python code that makes it. The user reads
    the code and runs it themselves, so keep it short and plain.

    The code must end with one top-level assignment to the name, eg `best = q1.sort("wins")["player"][-1]`.
    The value must be structured, one of:
    - a basic value: str, int, float, bool, datetime.date, datetime.datetime, datetime.time, datetime.timedelta
    - a list of basic values, all of one kind, eg ["Steve", "Sonic"]
    - a record: a frozen pydantic model whose fields are basic values or lists of them. Define its class in
      the code, before the assignment: `class PlayerSummary(BaseModel, frozen=True): ...` (`BaseModel` is
      already imported for you)
    - a table: a polars DataFrame (`pl` is polars). Several records are a DataFrame, never a list of records
    Never a dict, a tuple, a set, None or a list of dicts.

    Prefer computing the value from what the session has (its variables, `db`, the SmashDb) over writing it
    out: computed code is exact and shows where the value comes from. Set basis to "computed" then. When
    the value isn't in the session's data but you know it, or the chat so far states it, write it as a
    literal, eg `release = datetime.date(2018, 12, 7)` (`datetime` is already imported), and set basis to
    "knowledge". Don't refuse because something can't be computed: a literal is fine. Don't write out a
    table of more than about 30 rows from memory.

    Use only variables, tables and columns that are listed, written as the data has them. Variables the
    user mentions with @ are named without the @ in code. Earlier messages, when there are any, are the
    user's chat with the app's assistant (its answers and tool results): use them to understand what the
    user means. Allowed in the end: {ALLOWED}.

    Name: the user's, exactly as given, when they give one. Else pick a short snake_case name that says what
    it holds, not one that already exists, following Python's usual conventions for its type:
    """)
# joined, not inserted: a value of several lines would break clean_f_str's indent stripping
_INSTRUCTIONS = "\n".join([_INSTRUCTIONS, NAMING])


@dataclass
class AssignRun:
    """One proposal, for its check."""

    name: str
    """The name the user gave ("" = the AI picks one)."""
    taken: frozenset[str] = frozenset()
    """Names that exist already: one the AI picks must be new."""
    fixes: int = 0


assign_agent = Agent(
    DEFAULT_AI_MODEL,
    # on its Logfire spans (gen_ai.agent.name): the debug panel's Spend tab lists it apart from the chat
    name="inline-assign",
    # resolved at run time, so importing the app works without a key (as ds.ai.agent)
    defer_model_check=True,
    instructions=_INSTRUCTIONS,
    output_type=Assign,
    deps_type=AssignRun,
    retries=MAX_FIXES,
)


def split(text: str) -> tuple[str, str]:
    """What follows "/assign" as (name, what it should hold): "top5 = the five best" gives
    ("top5", "the five best"); without "name =" the name is "" (the AI picks one)."""
    named = _NAMED.fullmatch(text)
    if named is None:
        return "", text.strip()
    return named.group(1), named.group(2).strip()


def target(code: str) -> str:
    """The variable a snippet makes: the name its last top-level assignment binds ("" when it
    isn't Python, or doesn't end with a plain `name = ...`)."""
    try:
        body = ast.parse(code).body
    except SyntaxError:
        return ""
    last = body[-1] if body else None
    if isinstance(last, ast.Assign) and len(last.targets) == 1 and isinstance(last.targets[0], ast.Name):
        return last.targets[0].id
    if isinstance(last, ast.AnnAssign) and isinstance(last.target, ast.Name) and last.value is not None:
        return last.target.id
    return ""


def code_problem(code: str) -> str:
    """Why a snippet can't be run as an assignment ("" when it can); nothing is executed."""
    try:
        ast.parse(code)
    except SyntaxError as error:
        return f"That is not valid Python: {error}"
    if not target(code):
        return "The code must end with one top-level assignment to the variable, eg `name = ...`."
    return ""


@assign_agent.output_validator
async def check_proposal(ctx: RunContext[AssignRun], output: Assign) -> Assign:
    """Send a proposal that can't be run as an assignment back to the model, up to MAX_FIXES
    times; then show it anyway (the user can fix the code, and run() refuses what is wrong)."""
    asked = ctx.deps
    if asked.fixes >= MAX_FIXES:
        return output
    made = target(output.code)
    problem = code_problem(output.code)
    if not problem and asked.name and made != asked.name:
        problem = f"The user named the variable {asked.name}: the code must end by assigning {asked.name}, not {made}."
    if not problem and not asked.name and made in asked.taken:
        problem = f"{made} already exists: pick a name that isn't one of {', '.join(sorted(asked.taken))}."
    if problem:
        asked.fixes += 1
        raise ModelRetry(f"{problem} Send the corrected name and code.")
    return output


@dataclass
class Proposal:
    """What one "/assign" gave back: the code to review, or why there is none."""

    name: str = ""
    code: str = ""
    basis: str = ""
    """COMPUTED or KNOWLEDGE: whether the code works the value out or writes it out."""
    error: str = ""
    usage: str = ""
    """What the call used (TurnUsage.summary), "" when it never reached the model."""


async def propose(session: Session | None, token: str, text: str) -> Proposal:
    """Ask the model for the code of a new variable. text: what followed "/assign"."""
    name, what = split(text)
    if not what:
        return Proposal(error="Say what the variable should hold, eg: /assign top5 = the five best players in @q1")
    if session is not None and name and (problem := session.name_problem(name)):
        return Proposal(error=problem)
    if problem := mentions.problems(what, session):
        return Proposal(error=problem)
    # "@q1" in the text: what the variable holds goes along (no tools here). Built once: a call
    # such as "@q1.sample(5)" gives other rows each time it runs
    mentioned = mentions.context(what, session)
    wanted = f"Name it {name}." if name else "Pick its name."
    request = "\n\n".join(
        filter(
            None,
            [
                python_context("python", token, None),
                f"The new variable should hold: {what}\n{wanted}",
                mentioned,
            ],
        )
    )
    # the chat so far goes along (read only: the call is not added to the chat)
    history = list(session.ai_history) if session else []
    taken = frozenset(row["name"] for row in mentions.rows(session))
    asked = AssignRun(name=name, taken=taken)
    answer = Proposal()
    with (
        log_call("agent", "inline-assign", name="inline assign", prompt=text) as call,
        capture_run_messages() as captured,
    ):
        call["added"] = mentioned
        try:
            result = await assign_agent.run(request, message_history=history, deps=asked)
            output = result.output
            answer.name, answer.code, answer.basis = (
                target(output.code) or output.name,
                output.code.strip(),
                output.basis,
            )
        except Exception as error:  # noqa: BLE001  # shown in the chat row, not raised into the event
            call["error"] = answer.error = f"{type(error).__name__}: {error}"
        call["fixes"] = asked.fixes
        usage = log_usage(call, session, captured[len(history) :])
        if usage.requests:
            answer.usage = usage.summary()
    return answer


def _is_basic(value: Any) -> bool:
    return isinstance(value, BASIC)


def _list_problem(items: list[Any], what: str) -> str:
    odd = next((item for item in items if not _is_basic(item)), None)
    if odd is not None:
        hint = ": several records are a polars DataFrame" if isinstance(odd, dict | BaseModel) else ""
        return f"{what} holds a {type(odd).__name__}; a list may only hold basic values{hint}"
    # int and float mix as numbers; a bool is not a number here
    kinds = {"number" if type(item) in (int, float) else type(item).__name__ for item in items}
    if len(kinds) > 1:
        return f"{what} mixes {', '.join(sorted(kinds))}: a list holds one kind of value"
    return ""


def value_problem(value: Any) -> str:
    """Why a value can't be assigned ("" when it can): it must be structured, see ALLOWED."""
    match value:
        case pl.DataFrame():
            return ""
        case BaseModel():
            for name in type(value).model_fields:
                held = getattr(value, name)
                if held is None or _is_basic(held):
                    continue
                if isinstance(held, list):
                    if problem := _list_problem(held, f"field {name}"):
                        return problem
                    continue
                return f"field {name} is a {type(held).__name__}: a model's fields are basic values or lists of them"
            return ""
        case list():
            return _list_problem(value, "the list")
        case dict():
            return "a dict is unstructured: use a pydantic model (named, typed fields) or a polars DataFrame"
        case None:
            return "the value is None"
        case _ if _is_basic(value):
            return ""
        case _:
            return f"a {type(value).__name__} isn't allowed: {ALLOWED}"


@dataclass
class Ran:
    """What running a proposal's code did."""

    name: str = ""
    """The variable bound ("" when nothing was)."""
    error: str = ""
    """Why nothing was bound: a refused value in a line, or the code's traceback as plain text."""
    trace: list[dict[str, str]] = field(default_factory=list)
    """A traceback as styled parts (session.trace_parts), [] for a refusal."""
    classes: list[str] = field(default_factory=list)
    """Model classes the code defined, bound too (the record's type, to use again)."""
    replaced: bool = False


def run(session: Session, code: str) -> Ran:
    """Run a snippet and bind the variable it makes, when its value is allowed.

    It runs in a copy of the namespace, so nothing is bound when it fails or its value is
    refused, and helper names it made don't stay: only the variable, and a model class it
    defined. (Objects are shared with the copy: code that changes an existing value in place
    does change it, as in a cell.)
    """
    made = Ran()
    if problem := code_problem(code):
        return Ran(error=problem)
    name = target(code)
    if problem := session.name_problem(name):
        return Ran(error=problem)
    scratch = {**session.namespace, "BaseModel": BaseModel, "datetime": dt}
    before = dict(scratch)
    try:
        exec(compile(code, "</assign>", "exec"), scratch)  # noqa: S102  # code the user reviewed and ran
    except Exception as error:  # noqa: BLE001  # any error is shown under the code, not raised
        tb = error.__traceback__.tb_next if error.__traceback__ else None
        made.error = "".join(traceback.format_exception(type(error), error, tb))
        made.trace = trace_parts(error, tb)
        return made
    value = scratch[name]
    if problem := value_problem(value):
        return Ran(error=f"Not assigned: {problem}.")
    for other, held in scratch.items():
        new = other not in before or before[other] is not held
        if new and isinstance(held, type) and issubclass(held, BaseModel) and held is not BaseModel:
            session.namespace[other] = held
            made.classes.append(other)
    made.replaced = name in session.namespace
    session.namespace[name] = value
    session.sources[name] = SOURCE
    session.closed.pop(name, None)
    made.name = name
    return made
